        self.trusted = config.section("clients") or ()
        self.has_limits = config.section("limit") is not None
        self.clock = None
        self.states = {lim.name: {} for lim in self.limits}
        self.refused = {lim.name: 0 for lim in self.limits}


def setup(config):
    return State(config)


def _key(limit, ctx, client):
    """The key of the request for this limit, or None when a key part has no value."""
    out = []
