    if not isinstance(items, list) or not all(isinstance(x, str) for x in items):
        raise ConfigError(f"{what}: {key} must be a list of networks")
    out = []
    for text in items:
        prefix = text.partition("/")[2] if "/" in text else "0"
        if "%" in text or not (prefix.isascii() and prefix.isdigit()):
            raise ConfigError(f"{what}: {text!r} is not a network")
